<?php

namespace Database\Seeders;

use App\Models\Category;
use App\Models\Option;
use App\Models\Question;
use Illuminate\Database\Seeder;

class QuestionsSeeder extends Seeder
{
    public function run(): void
    {
        $categories = $this->seedCategories();
        $this->seedQuestions($categories);
        $this->command->info('Seeded 400 questions across 5 categories.');
    }

    private function seedCategories(): array
    {
        $data = [
            ['name' => 'Road Signs',         'slug' => 'road-signs',       'icon' => '🚸', 'description' => 'Traffic signs, warning signs, and regulatory signs'],
            ['name' => 'Traffic Rules',       'slug' => 'traffic-rules',    'icon' => '📋', 'description' => 'Laws and regulations governing road use'],
            ['name' => 'Vehicle Control',     'slug' => 'vehicle-control',  'icon' => '🚗', 'description' => 'Safe vehicle operation and handling'],
            ['name' => 'Road Safety',         'slug' => 'road-safety',      'icon' => '⛑️',  'description' => 'Safety practices and accident prevention'],
            ['name' => 'First Aid & Emergencies', 'slug' => 'first-aid',   'icon' => '🚑', 'description' => 'Emergency response and basic first aid'],
        ];

        $categories = [];
        foreach ($data as $cat) {
            $categories[$cat['slug']] = Category::firstOrCreate(
                ['slug' => $cat['slug']],
                $cat
            );
        }

        return $categories;
    }

    private function seedQuestions(array $categories): void
    {
        $questions = $this->getQuestionBank($categories);

        foreach ($questions as $qData) {
            $question = Question::create([
                'category_id'   => $qData['category_id'],
                'question_text' => $qData['question'],
                'difficulty'    => $qData['difficulty'],
                'explanation'   => $qData['explanation'],
                'is_active'     => true,
            ]);

            foreach ($qData['options'] as $index => $opt) {
                Option::create([
                    'question_id' => $question->id,
                    'option_text' => $opt['text'],
                    'is_correct'  => $opt['correct'],
                    'order'       => $index,
                ]);
            }
        }
    }

    private function getQuestionBank(array $cats): array
