            'category_id' => $cat,
            'question'    => $question,
            'difficulty'  => $diff,
            'explanation' => $exp,
            'options'     => collect($opts)->map(fn($o, $i) => [
                'text'    => $o,
                'correct' => $i === $correct,
            ])->values()->all(),
