            $q($rs, 'A sign showing a person walking indicates:', ['Pedestrian crossing ahead', 'School zone', 'No pedestrians', 'Walking trail'], 0, 'easy', 'This warning sign tells drivers a pedestrian crossing is ahead.'),
            $q($rs, 'What does a red circle with a diagonal line through a symbol mean?', ['That action is prohibited', 'That action is mandatory', 'That action is recommended', 'Warning of danger'], 0, 'easy', 'A red circle with diagonal line (prohibition sign) means the action is forbidden.'),
            $q($rs, 'The sign showing a truck on a slope means:', ['Steep hill ahead', 'Trucks only lane', 'No trucks allowed', 'Truck loading zone'], 0, 'medium', 'This sign warns of a steep gradient ahead, particularly relevant for heavy vehicles.'),
            $q($rs, 'A sign with a "!" (exclamation) in a triangle warns:', ['General hazard ahead', 'Stop required', 'Speed bump', 'Railway crossing'], 0, 'easy', 'An exclamation mark in a warning triangle indicates a general hazard.'),
            $q($rs, 'What does a green sign with an arrow typically indicate?', ['Direction to a destination', 'Mandatory turn', 'No entry', 'Speed limit'], 0, 'easy', 'Green directional signs guide drivers toward destinations and junctions.'),
            $q($rs, 'A zigzag line painted on the road near a crossing means:', ['No stopping or parking', 'Slow down area', 'School zone boundary', 'Bus stop zone'], 0, 'medium', 'Zigzag markings near crossings prohibit stopping and parking to keep crossing visible.'),
            $q($rs, 'What does a sign with two cars side by side (one red, one blue) indicate?', ['Overtaking is prohibited', 'Use both lanes', 'Lane merge ahead', 'Car park entrance'], 0, 'medium', 'This sign prohibits overtaking — passing another vehicle is not allowed.'),
            $q($rs, 'A "Give Way" sign requires you to:', ['Yield to traffic on the main road', 'Stop completely before proceeding', 'Speed up to merge', 'Flash your lights'], 0, 'easy', 'Give Way means yield — slow down and give priority to crossing traffic.'),
