            $q($rs, 'What does a speed limit sign (e.g. "50") inside a red circle mean?', ['Maximum speed is 50 km/h', 'Minimum speed is 50 km/h', 'Average speed check', 'Recommended speed'], 0, 'easy', 'Speed limit signs in red circles show the maximum legal speed in km/h.'),
